        const inputId = `${questionId}-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${inputId}">
            <input id="${inputId}" name="${questionId}" type="checkbox" value="${escapeHtml(label)}">
            <span class="choice-text">${escapeHtml(label)}</span>
          </label>
        `;
      }

      function QuestionField({ id, question, help, choices }) {
        const helpId = `${id}-help`;
        const describedBy = help ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${escapeHtml(question)}</legend>
              ${help ? `<p class="help-text" id="${helpId}">${escapeHtml(help)}</p>` : ""}
