        return `
          <section class="quiz-shell" aria-labelledby="quiz-title">
            <p class="eyebrow">Multiple selection quiz</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="intro">
              Test your knowledge of computer languages and web technologies.
              Each question can have more than one answer.
            </p>
            <form id="quiz-form">
              ${questions.map(QuestionField).join("")}
              <div class="actions">
                <button type="submit">Submit answers</button>
                <p class="status" id="quiz-status" aria-live="polite"></p>
